def generate_post(title, content):
    import html

    if not isinstance(title, str) or not isinstance(content, str):
        raise TypeError("title and content must be strings")

    escaped_title = html.escape(title, quote=False)
    escaped_content = html.escape(content, quote=False)

    return (
        "<html><head><title>"
        + escaped_title
        + "</title></head><body>"
        + escaped_content
        + "</body></html>"
    )
